package com.codeguardian.controller; import com.codeguardian.entity.Finding; import com.codeguardian.service.rules.RuleEngineService; import lombok.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/rules") @RequiredArgsConstructor public class RuleTemplateController{private final RuleEngineService rules;@GetMapping("/templates") public Set<String> templates(){return rules.templates();}@PostMapping("/review") public List<Finding> review(@RequestBody RuleReviewRequest r){return rules.reviewWithTemplate(r.code,r.language,r.template);}@Data public static class RuleReviewRequest{String code,language,template;}}
